            id: tasks.length + 1,
            text: text,
            completed: false
        };

        tasks.push(newTask);
        res.json(newTask);
    });

    // Start Server
    app.listen(PORT, () => {
        console.log(`Server running on http://localhost:${PORT}`);
    });
